    solution: "CREATE TABLE wishlist (customer_id INTEGER REFERENCES customers(customer_id), stock_code TEXT REFERENCES products(stock_code), added_at TEXT NOT NULL, PRIMARY KEY (customer_id, stock_code)); INSERT INTO wishlist VALUES (12347, '85123A', '2011-12-01'), (12347, '22423', '2011-12-02'); SELECT customer_id, stock_code, added_at FROM wishlist",
